using System.ComponentModel;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides web search capabilities as an AI tool.
/// In production, replace the simulated results with a real search API (e.g., Bing Search).
/// </summary>
public sealed class WebSearchService
{
    private static readonly Dictionary<string, string[]> SimulatedResults = new(StringComparer.OrdinalIgnoreCase)
    {
        ["quantum computing"] =
        [
            "Quantum computers use qubits that can exist in superposition, enabling parallel computation. IBM and Google have achieved quantum supremacy milestones.",
            "Error correction remains the biggest challenge. Current quantum computers are 'noisy intermediate-scale quantum' (NISQ) devices with limited qubit counts.",
            "Applications include cryptography, drug discovery, optimization problems, and materials science. Commercial availability is expected within the next decade."
        ],
        ["artificial intelligence"] =
        [
            "Large language models (LLMs) have transformed AI, enabling human-like text generation and reasoning. GPT-4, Claude, and Gemini lead the field.",
            "AI safety and alignment research is accelerating as models become more capable. Governments worldwide are implementing AI regulation frameworks.",
            "Edge AI and on-device inference are growing trends, reducing latency and improving privacy for consumer applications."
        ],
    };

    [Description("Search the web for information on a given query. Returns a list of relevant search result snippets.")]
    public Task<string[]> SearchWebAsync(
        [Description("The search query to look up on the web")] string query)
    {
        // Simulate web search - in production, call Bing Search API or similar
        foreach (var (key, results) in SimulatedResults)
        {
            if (query.Contains(key, StringComparison.OrdinalIgnoreCase))
            {
                return Task.FromResult(results);
            }
        }

        return Task.FromResult(new[]
        {
            $"Search result 1 for '{query}': General information about {query} from Wikipedia.",
            $"Search result 2 for '{query}': Recent research papers discuss advances in {query}.",
            $"Search result 3 for '{query}': Industry experts predict significant growth in {query} by 2030."
        });
    }

    public static AIFunction CreateTool(WebSearchService service)
    {
        return AIFunctionFactory.Create(service.SearchWebAsync, nameof(SearchWebAsync));
    }
}

using System.ComponentModel;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides note-taking capabilities as an AI tool.
/// The agent uses this to record findings during research.
/// </summary>
public sealed class NoteService
{
    private readonly List<NoteEntry> _notes = [];

    [Description("Save a research note with a title and content. Use this to record important findings during research.")]
    public Task<string> SaveNoteAsync(
        [Description("A short title for the note")] string title,
        [Description("The content/body of the note")] string content)
    {
        var entry = new NoteEntry(title, content, DateTime.UtcNow);
        _notes.Add(entry);
        return Task.FromResult($"Note saved: '{title}' ({_notes.Count} total notes)");
    }

    [Description("Retrieve all saved research notes.")]
    public Task<NoteEntry[]> GetAllNotesAsync()
    {
        return Task.FromResult(_notes.ToArray());
    }

    public IReadOnlyList<NoteEntry> Notes => _notes;

    public static AIFunction[] CreateTools(NoteService service)
    {
        return
        [
            AIFunctionFactory.Create(service.SaveNoteAsync, nameof(SaveNoteAsync)),
            AIFunctionFactory.Create(service.GetAllNotesAsync, nameof(GetAllNotesAsync)),
        ];
    }
}

public sealed record NoteEntry(string Title, string Content, DateTime Timestamp);

using Microsoft.Extensions.AI;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;

namespace ResearchAgent;

public sealed class ResearchHostedService(
    IChatClient chatClient,
    NoteService noteService,
    WebSearchService webSearchService,
    IHostApplicationLifetime lifetime,
    ILogger<ResearchHostedService> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        try
        {
            await RunResearchAgentAsync(stoppingToken);
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "Research agent failed");
        }
        finally
        {
            lifetime.StopApplication();
        }
    }

    private async Task RunResearchAgentAsync(CancellationToken cancellationToken)
    {
        Console.WriteLine("=== Research Agent ===");
        Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
        Console.Write("> ");

        var topic = Console.ReadLine()?.Trim();
        if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        {
            Console.WriteLine("Goodbye!");
            return;
        }

        Console.WriteLine($"\nResearching: {topic}...\n");

        var tools = new List<AITool>
        {
            WebSearchService.CreateTool(webSearchService),
            ..NoteService.CreateTools(noteService),
        };

        var agent = new ChatClientAgent(chatClient, "ResearchAgent")
        {
            Instructions = """
                You are a research agent. Your job is to thoroughly research a topic using web search,
                take organized notes on your findings, and then provide a comprehensive summary.

                Follow this process:
                1. Search the web for information about the topic
                2. Save important findings as notes with clear titles
                3. Search for additional aspects or subtopics if needed
                4. Review all your notes
                5. Provide a final comprehensive summary of your research

                Be thorough but concise. Organize your findings logically.
                """,
            Tools = tools,
        };

        var options = new AgentInvokeOptions
        {
            MaximumIterations = 10,
        };

        var history = new List<ChatMessage>
        {
            new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
        };

        Console.WriteLine("--- Agent Working ---\n");

        await foreach (var message in agent.InvokeStreamingAsync(history, options, cancellationToken))
        {
            if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
            {
                Console.Write(message.Text);
            }

            logger.LogDebug("Agent step: Role={Role}, ContentLength={Length}",
                message.Role, message.Text?.Length ?? 0);
        }

        Console.WriteLine("\n\n--- Research Complete ---");
        Console.WriteLine($"Notes taken: {noteService.Notes.Count}");

        foreach (var note in noteService.Notes)
        {
            Console.WriteLine($"  • {note.Title}");
        }
    }
}

