using System.ComponentModel;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides web search capabilities as an AI tool.
/// In production, replace the simulated results with a real search API (e.g., Bing Search).
/// </summary>
public sealed class WebSearchService
{
    private static readonly Dictionary<string, string[]> SimulatedResults = new(StringComparer.OrdinalIgnoreCase)
    {
        ["quantum computing"] =
        [
            "Quantum computers use qubits that can exist in superposition, enabling parallel computation. IBM and Google have achieved quantum supremacy milestones.",
            "Error correction remains the biggest challenge. Current quantum computers are 'noisy intermediate-scale quantum' (NISQ) devices with limited qubit counts.",
            "Applications include cryptography, drug discovery, optimization problems, and materials science. Commercial availability is expected within the next decade."
        ],
        ["artificial intelligence"] =
        [
            "Large language models (LLMs) have transformed AI, enabling human-like text generation and reasoning. GPT-4, Claude, and Gemini lead the field.",
            "AI safety and alignment research is accelerating as models become more capable. Governments worldwide are implementing AI regulation frameworks.",
            "Edge AI and on-device inference are growing trends, reducing latency and improving privacy for consumer applications."
        ],
    };

    [Description("Search the web for information on a given query. Returns a list of relevant search result snippets.")]
    public Task<string[]> SearchWebAsync(
        [Description("The search query to look up on the web")] string query)
    {
        // Simulate web search - in production, call Bing Search API or similar
        foreach (var (key, results) in SimulatedResults)
        {
            if (query.Contains(key, StringComparison.OrdinalIgnoreCase))
            {
                return Task.FromResult(results);
            }
        }

        return Task.FromResult(new[]
        {
            $"Search result 1 for '{query}': General information about {query} from Wikipedia.",
            $"Search result 2 for '{query}': Recent research papers discuss advances in {query}.",
            $"Search result 3 for '{query}': Industry experts predict significant growth in {query} by 2030."
        });
    }

    public static AIFunction CreateTool(WebSearchService service)
    {
        return AIFunctionFactory.Create(service.SearchWebAsync, nameof(SearchWebAsync));
    }
}

