using System.ComponentModel;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides note-taking capabilities as an AI tool.
/// The agent uses this to record findings during research.
/// </summary>
public sealed class NoteService
{
    private readonly List<NoteEntry> _notes = [];

    [Description("Save a research note with a title and content. Use this to record important findings during research.")]
    public Task<string> SaveNoteAsync(
        [Description("A short title for the note")] string title,
        [Description("The content/body of the note")] string content)
    {
        var entry = new NoteEntry(title, content, DateTime.UtcNow);
        _notes.Add(entry);
        return Task.FromResult($"Note saved: '{title}' ({_notes.Count} total notes)");
    }

    [Description("Retrieve all saved research notes.")]
    public Task<NoteEntry[]> GetAllNotesAsync()
    {
        return Task.FromResult(_notes.ToArray());
    }

    public IReadOnlyList<NoteEntry> Notes => _notes;

    public static AIFunction[] CreateTools(NoteService service)
    {
        return
        [
            AIFunctionFactory.Create(service.SaveNoteAsync, nameof(SaveNoteAsync)),
            AIFunctionFactory.Create(service.GetAllNotesAsync, nameof(GetAllNotesAsync)),
        ];
    }
}

public sealed record NoteEntry(string Title, string Content, DateTime Timestamp);

