using Microsoft.Extensions.AI;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;

namespace ResearchAgent;

public sealed class ResearchHostedService(
    IChatClient chatClient,
    NoteService noteService,
    WebSearchService webSearchService,
    IHostApplicationLifetime lifetime,
    ILogger<ResearchHostedService> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        try
        {
            await RunResearchAgentAsync(stoppingToken);
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "Research agent failed");
        }
        finally
        {
            lifetime.StopApplication();
        }
    }

    private async Task RunResearchAgentAsync(CancellationToken cancellationToken)
    {
        Console.WriteLine("=== Research Agent ===");
        Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
        Console.Write("> ");

        var topic = Console.ReadLine()?.Trim();
        if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        {
            Console.WriteLine("Goodbye!");
            return;
        }

        Console.WriteLine($"\nResearching: {topic}...\n");

        var tools = new List<AITool>
        {
            WebSearchService.CreateTool(webSearchService),
        };
        tools.AddRange(NoteService.CreateTools(noteService));

        var agent = new ChatClientAgent(
            chatClient,
            instructions: """
                You are a research agent. Your job is to thoroughly research a topic using web search,
                take organized notes on your findings, and then provide a comprehensive summary.

                Follow this process:
                1. Search the web for information about the topic
                2. Save important findings as notes with clear titles
                3. Search for additional aspects or subtopics if needed
                4. Review all your notes
                5. Provide a final comprehensive summary of your research

                Be thorough but concise. Organize your findings logically.
                """,
            name: "ResearchAgent",
            tools: tools);

        var message = new ChatMessage(
            ChatRole.User,
            $"Research the following topic and provide a comprehensive summary: {topic}");

        Console.WriteLine("--- Agent Working ---\n");

        await foreach (var update in agent.RunStreamingAsync(
            message, session: null, options: null, cancellationToken))
        {
            if (!string.IsNullOrEmpty(update.Text))
            {
                Console.Write(update.Text);
            }

            logger.LogDebug("Agent step: Role={Role}, ContentLength={Length}",
                update.Role, update.Text?.Length ?? 0);
        }

        Console.WriteLine("\n\n--- Research Complete ---");
        Console.WriteLine($"Notes taken: {noteService.Notes.Count}");

        foreach (var note in noteService.Notes)
        {
            Console.WriteLine($"  • {note.Title}");
        }
    }
}

